values (
  'en-spider-man-trivia',
  'Spider-Man Fan Trivia Challenge',
  'From the pages of Amazing Fantasy to the big screen: more than sixty years of the web-slinger. How much do you know about Spidey?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Who created Spider-Man?","options":[{"id":"a","text":"Stan Lee and Jack Kirby","is_correct":false},{"id":"b","text":"Stan Lee and Steve Ditko","is_correct":true},{"id":"c","text":"Bob Kane and Bill Finger","is_correct":false},{"id":"d","text":"Jerry Siegel and Joe Shuster","is_correct":false}],"explanation":"Stan Lee wrote and Steve Ditko drew the character in 1962; the other pairs created Batman and Superman for DC."},{"id":"q2","question":"In which comic did Spider-Man make his first appearance?","options":[{"id":"a","text":"The Amazing Spider-Man #1","is_correct":false},{"id":"b","text":"Fantastic Four #1","is_correct":false},{"id":"c","text":"Amazing Fantasy #15","is_correct":true},{"id":"d","text":"Tales to Astonish #27","is_correct":false}],"explanation":"Amazing Fantasy #15 came out in August 1962; The Amazing Spider-Man #1 arrived a few months later, in 1963."},{"id":"q3","question":"What is Peter Parker''s job at the Daily Bugle?","options":[{"id":"a","text":"Photographer","is_correct":true},{"id":"b","text":"Reporter","is_correct":false},{"id":"c","text":"Editor-in-chief","is_correct":false},{"id":"d","text":"Intern","is_correct":false}],"explanation":"Peter sells freelance photos of Spider-Man to the paper — run by J. Jonah Jameson, Spider-Man''s loudest critic."},{"id":"q4","question":"Who played Spider-Man in Sam Raimi''s film trilogy?","options":[{"id":"a","text":"Andrew Garfield","is_correct":false},{"id":"b","text":"Tom Holland","is_correct":false},{"id":"c","text":"Jake Gyllenhaal","is_correct":false},{"id":"d","text":"Tobey Maguire","is_correct":true}],"explanation":"Tobey Maguire starred in the 2002–2007 trilogy; Andrew Garfield and Tom Holland played later versions."},{"id":"q5","question":"What is the name of the aunt who raised Peter Parker?","options":[{"id":"a","text":"May","is_correct":true},{"id":"b","text":"Mary Jane","is_correct":false},{"id":"c","text":"Gwen","is_correct":false},{"id":"d","text":"Betty","is_correct":false}],"explanation":"Aunt May raised Peter with Uncle Ben, whose death teaches him that great power brings great responsibility."},{"id":"q6","question":"Which Spider-Man villain is a scientist with four mechanical arms?","options":[{"id":"a","text":"The Green Goblin","is_correct":false},{"id":"b","text":"Doctor Octopus","is_correct":true},{"id":"c","text":"Sandman","is_correct":false},{"id":"d","text":"The Lizard","is_correct":false}],"explanation":"Doctor Otto Octavius fuses four tentacle-like arms to his body in a lab accident — the villain of Spider-Man 2 (2004)."},{"id":"q7","question":"How does Peter Parker get his powers?","options":[{"id":"a","text":"A military experiment","is_correct":false},{"id":"b","text":"An accident with gamma rays","is_correct":false},{"id":"c","text":"A bite from a radioactive spider","is_correct":true},{"id":"d","text":"A bat bite","is_correct":false}],"explanation":"A radioactive spider bites him during a school visit to a science exhibition, giving him his powers."},{"id":"q8","question":"Which animated film starring Miles Morales won the Oscar for Best Animated Feature in 2019?","options":[{"id":"a","text":"Spider-Man: Far From Home","is_correct":false},{"id":"b","text":"The Amazing Spider-Man","is_correct":false},{"id":"c","text":"Spider-Man: Homecoming","is_correct":false},{"id":"d","text":"Spider-Man: Into the Spider-Verse","is_correct":true}],"explanation":"Spider-Man: Into the Spider-Verse (2018) won the Oscar; the other three are live-action films."}]'::jsonb,
  null,
  array['spider-man', 'marvel', 'movies', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
