  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"What is the name of the underwater city where SpongeBob lives?","options":[{"id":"a","text":"Atlantis","is_correct":false},{"id":"b","text":"Bikini Bottom","is_correct":true},{"id":"c","text":"Coral City","is_correct":false},{"id":"d","text":"Shell City","is_correct":false}],"explanation":"Bikini Bottom sits under Bikini Atoll in the Pacific Ocean — hence its name."},{"id":"q2","question":"What is the name of SpongeBob''s best friend, a pink starfish?","options":[{"id":"a","text":"Squidward","is_correct":false},{"id":"b","text":"Sandy","is_correct":false},{"id":"c","text":"Patrick","is_correct":true},{"id":"d","text":"Mr. Krabs","is_correct":false}],"explanation":"Patrick Star lives under a rock next to SpongeBob''s pineapple house."},{"id":"q3","question":"At which restaurant does SpongeBob work as a fry cook?","options":[{"id":"a","text":"The Chum Bucket","is_correct":false},{"id":"b","text":"The Salty Spitoon","is_correct":false},{"id":"c","text":"Weenie Hut Jr''s","is_correct":false},{"id":"d","text":"The Krusty Krab","is_correct":true}],"explanation":"The Krusty Krab is Mr. Krabs'' restaurant; the Chum Bucket across the street belongs to Plankton."},{"id":"q4","question":"What secret formula is Plankton always trying to steal?","options":[{"id":"a","text":"The Krabby Patty formula","is_correct":true},{"id":"b","text":"The kelp juice recipe","is_correct":false},{"id":"c","text":"The coral pizza dough","is_correct":false},{"id":"d","text":"The jellyfish jelly recipe","is_correct":false}],"explanation":"Plankton''s whole life revolves around stealing the Krabby Patty secret formula from Mr. Krabs."},{"id":"q5","question":"What kind of animal is Sandy Cheeks?","options":[{"id":"a","text":"A mouse","is_correct":false},{"id":"b","text":"A squirrel","is_correct":true},{"id":"c","text":"A rabbit","is_correct":false},{"id":"d","text":"An otter","is_correct":false}],"explanation":"Sandy is a squirrel from Texas who lives underwater inside an air-filled treedome."},{"id":"q6","question":"Who created SpongeBob SquarePants?","options":[{"id":"a","text":"Matt Groening","is_correct":false},{"id":"b","text":"Seth MacFarlane","is_correct":false},{"id":"c","text":"Butch Hartman","is_correct":false},{"id":"d","text":"Stephen Hillenburg","is_correct":true}],"explanation":"Marine science educator Stephen Hillenburg created the show, which premiered on Nickelodeon in 1999."},{"id":"q7","question":"Which instrument does Squidward play?","options":[{"id":"a","text":"The clarinet","is_correct":true},{"id":"b","text":"The flute","is_correct":false},{"id":"c","text":"The trumpet","is_correct":false},{"id":"d","text":"The saxophone","is_correct":false}],"explanation":"Squidward''s terrible clarinet playing is one of the show''s longest-running gags."},{"id":"q8","question":"What is the name of SpongeBob''s pet snail?","options":[{"id":"a","text":"Larry","is_correct":false},{"id":"b","text":"Gary","is_correct":true},{"id":"c","text":"Spot","is_correct":false},{"id":"d","text":"Jerry","is_correct":false}],"explanation":"Gary meows like a cat; Larry is the lobster lifeguard and Spot is Plankton''s pet amoeba."}]'::jsonb,
  null,
  array['spongebob', 'tv-shows', 'nickelodeon', 'trivia']::text[],
