  '[{"id":"q1","question":"¿Cómo se llama la ciudad submarina donde vive Bob Esponja?","options":[{"id":"a","text":"Fondo de Bikini","is_correct":true},{"id":"b","text":"Atlántida","is_correct":false},{"id":"c","text":"Ciudad Coral","is_correct":false},{"id":"d","text":"Villa Marina","is_correct":false}],"explanation":"Fondo de Bikini está bajo el atolón Bikini, en el océano Pacífico; de ahí viene su nombre."},{"id":"q2","question":"¿Cómo se llama el mejor amigo de Bob Esponja, una estrella de mar rosa?","options":[{"id":"a","text":"Calamardo","is_correct":false},{"id":"b","text":"Patricio","is_correct":true},{"id":"c","text":"Arenita","is_correct":false},{"id":"d","text":"Don Cangrejo","is_correct":false}],"explanation":"Patricio Estrella vive bajo una roca, al lado de la casa piña de Bob Esponja."},{"id":"q3","question":"¿En qué restaurante trabaja Bob Esponja como cocinero?","options":[{"id":"a","text":"El Balde de Carnada","is_correct":false},{"id":"b","text":"El Crustáceo Cascarudo","is_correct":true},{"id":"c","text":"El Sazón Salado","is_correct":false},{"id":"d","text":"La cocina de Plankton","is_correct":false}],"explanation":"El Crustáceo Cascarudo es el restaurante de Don Cangrejo; el Balde de Carnada, enfrente, es de Plankton."},{"id":"q4","question":"¿Qué fórmula secreta intenta robar Plankton una y otra vez?","options":[{"id":"a","text":"La receta del jugo de algas","is_correct":false},{"id":"b","text":"La masa de la pizza de coral","is_correct":false},{"id":"c","text":"La fórmula de la Cangreburger","is_correct":true},{"id":"d","text":"La receta de la jalea de medusa","is_correct":false}],"explanation":"Toda la vida de Plankton gira en torno a robar la fórmula secreta de la Cangreburger a Don Cangrejo."},{"id":"q5","question":"¿Qué clase de animal es Arenita Mejillas?","options":[{"id":"a","text":"Una ardilla","is_correct":true},{"id":"b","text":"Una rata","is_correct":false},{"id":"c","text":"Una coneja","is_correct":false},{"id":"d","text":"Una nutria","is_correct":false}],"explanation":"Arenita es una ardilla de Texas que vive bajo el mar dentro de una cúpula con aire."},{"id":"q6","question":"¿Quién creó Bob Esponja?","options":[{"id":"a","text":"Matt Groening","is_correct":false},{"id":"b","text":"Seth MacFarlane","is_correct":false},{"id":"c","text":"Stephen Hillenburg","is_correct":true},{"id":"d","text":"Butch Hartman","is_correct":false}],"explanation":"Stephen Hillenburg, biólogo marino, creó la serie que Nickelodeon estrenó en 1999."},{"id":"q7","question":"¿Qué instrumento toca Calamardo?","options":[{"id":"a","text":"La flauta","is_correct":false},{"id":"b","text":"El clarinete","is_correct":true},{"id":"c","text":"La trompeta","is_correct":false},{"id":"d","text":"El saxofón","is_correct":false}],"explanation":"Lo mal que toca Calamardo el clarinete es uno de los chistes más largos de la serie."},{"id":"q8","question":"¿Cómo se llama el caracol mascota de Bob Esponja?","options":[{"id":"a","text":"Larry","is_correct":false},{"id":"b","text":"Spot","is_correct":false},{"id":"c","text":"Jerry","is_correct":false},{"id":"d","text":"Gary","is_correct":true}],"explanation":"Gary maúlla como un gato; Larry es la langosta salvavidas y Spot la ameba mascota de Plankton."}]'::jsonb,
