values (
  'en-shrek-trivia',
  'Shrek Fan Trivia Challenge',
  'Ogres, onions and the swamp that changed animation: the DreamWorks saga that parodied every fairy tale. How much do you know?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In which year was the first Shrek film released?","options":[{"id":"a","text":"1999","is_correct":false},{"id":"b","text":"2001","is_correct":true},{"id":"c","text":"2003","is_correct":false},{"id":"d","text":"2005","is_correct":false}],"explanation":"Shrek premiered in May 2001; Shrek 2 followed in 2004."},{"id":"q2","question":"Which studio produced Shrek?","options":[{"id":"a","text":"Pixar","is_correct":false},{"id":"b","text":"Disney","is_correct":false},{"id":"c","text":"DreamWorks","is_correct":true},{"id":"d","text":"Blue Sky","is_correct":false}],"explanation":"DreamWorks Animation made Shrek as a pointed parody of the Disney fairy-tale formula."},{"id":"q3","question":"Who voices Shrek in the original films?","options":[{"id":"a","text":"Eddie Murphy","is_correct":false},{"id":"b","text":"Mike Myers","is_correct":true},{"id":"c","text":"Cameron Diaz","is_correct":false},{"id":"d","text":"John Lithgow","is_correct":false}],"explanation":"Mike Myers gave Shrek his Scottish accent; Eddie Murphy is Donkey, Cameron Diaz is Fiona and John Lithgow is Farquaad."},{"id":"q4","question":"Who voices Donkey?","options":[{"id":"a","text":"Chris Rock","is_correct":false},{"id":"b","text":"Chris Tucker","is_correct":false},{"id":"c","text":"Eddie Murphy","is_correct":true},{"id":"d","text":"Antonio Banderas","is_correct":false}],"explanation":"Eddie Murphy improvised much of Donkey''s chatter; Antonio Banderas is Puss in Boots."},{"id":"q5","question":"Shrek made history as the first winner of which Oscar category?","options":[{"id":"a","text":"Best Animated Feature","is_correct":true},{"id":"b","text":"Best Picture","is_correct":false},{"id":"c","text":"Best Original Song","is_correct":false},{"id":"d","text":"Best Visual Effects","is_correct":false}],"explanation":"At the 2002 ceremony Shrek won the first-ever Oscar for Best Animated Feature, beating Monsters, Inc."},{"id":"q6","question":"What is the name of the princess Shrek rescues from the tower?","options":[{"id":"a","text":"Rapunzel","is_correct":false},{"id":"b","text":"Cinderella","is_correct":false},{"id":"c","text":"Sleeping Beauty","is_correct":false},{"id":"d","text":"Fiona","is_correct":true}],"explanation":"Princess Fiona carries a curse: she turns into an ogre every night."},{"id":"q7","question":"Who is the villain of the first film, the diminutive ruler of Duloc?","options":[{"id":"a","text":"Lord Farquaad","is_correct":true},{"id":"b","text":"Prince Charming","is_correct":false},{"id":"c","text":"Rumpelstiltskin","is_correct":false},{"id":"d","text":"The Fairy Godmother","is_correct":false}],"explanation":"Lord Farquaad banishes the fairy-tale creatures to Shrek''s swamp; the others are villains of the sequels."},{"id":"q8","question":"Which band performs ''All Star'' over the film''s opening?","options":[{"id":"a","text":"Green Day","is_correct":false},{"id":"b","text":"Smash Mouth","is_correct":true},{"id":"c","text":"Queen","is_correct":false},{"id":"d","text":"Oasis","is_correct":false}],"explanation":"Smash Mouth''s ''All Star'' plays over the opening and their cover of ''I''m a Believer'' closes the film."}]'::jsonb,
  null,
  array['shrek', 'dreamworks', 'movies', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
