  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In which year did the original Star Trek series debut on television?","options":[{"id":"a","text":"1962","is_correct":false},{"id":"b","text":"1966","is_correct":true},{"id":"c","text":"1972","is_correct":false},{"id":"d","text":"1979","is_correct":false}],"explanation":"Star Trek premiered on NBC on 8 September 1966; the first film arrived in 1979."},{"id":"q2","question":"Who created Star Trek?","options":[{"id":"a","text":"George Lucas","is_correct":false},{"id":"b","text":"J.J. Abrams","is_correct":false},{"id":"c","text":"Gene Roddenberry","is_correct":true},{"id":"d","text":"Isaac Asimov","is_correct":false}],"explanation":"Gene Roddenberry, a former pilot and police officer, pitched it as a ''western in space''."},{"id":"q3","question":"What is the name of Captain Kirk''s starship?","options":[{"id":"a","text":"USS Enterprise","is_correct":true},{"id":"b","text":"USS Voyager","is_correct":false},{"id":"c","text":"USS Defiant","is_correct":false},{"id":"d","text":"USS Discovery","is_correct":false}],"explanation":"The USS Enterprise NCC-1701 carries Kirk''s five-year mission; the others star in later series."},{"id":"q4","question":"Spock is half human and half of which alien species?","options":[{"id":"a","text":"Klingon","is_correct":false},{"id":"b","text":"Romulan","is_correct":false},{"id":"c","text":"Andorian","is_correct":false},{"id":"d","text":"Vulcan","is_correct":true}],"explanation":"Spock''s father Sarek is Vulcan and his mother Amanda is human."},{"id":"q5","question":"Which phrase accompanies the Vulcan salute?","options":[{"id":"a","text":"''Live long and prosper''","is_correct":true},{"id":"b","text":"''May the Force be with you''","is_correct":false},{"id":"c","text":"''Resistance is futile''","is_correct":false},{"id":"d","text":"''Make it so''","is_correct":false}],"explanation":"''Live long and prosper'' goes with the raised-hand V sign; the Force line is Star Wars, ''Resistance is futile'' is the Borg and ''Make it so'' is Picard."},{"id":"q6","question":"Who commands the Enterprise in Star Trek: The Next Generation?","options":[{"id":"a","text":"James Kirk","is_correct":false},{"id":"b","text":"Benjamin Sisko","is_correct":false},{"id":"c","text":"Jean-Luc Picard","is_correct":true},{"id":"d","text":"Kathryn Janeway","is_correct":false}],"explanation":"Captain Jean-Luc Picard leads the Enterprise-D; Sisko commands Deep Space Nine and Janeway commands Voyager."},{"id":"q7","question":"What device beams the crew instantly between the ship and a planet''s surface?","options":[{"id":"a","text":"The warp drive","is_correct":false},{"id":"b","text":"The transporter","is_correct":true},{"id":"c","text":"The holodeck","is_correct":false},{"id":"d","text":"The shuttlecraft","is_correct":false}],"explanation":"The transporter converts matter to energy and back — ''beam me up'' is the fan shorthand, though the exact phrase was never said that way."},{"id":"q8","question":"Who played Spock in the original series?","options":[{"id":"a","text":"William Shatner","is_correct":false},{"id":"b","text":"Leonard Nimoy","is_correct":true},{"id":"c","text":"DeForest Kelley","is_correct":false},{"id":"d","text":"Zachary Quinto","is_correct":false}],"explanation":"Leonard Nimoy originated Spock; William Shatner is Kirk, DeForest Kelley is McCoy and Zachary Quinto plays the reboot version."}]'::jsonb,
  null,
  array['star-trek', 'sci-fi', 'tv-shows', 'trivia']::text[],
