insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-lego-trivia',
  'LEGO Fan Trivia Challenge',
  'Studs, minifigures and a Danish word for ''play well'': the brick that built a universe of toys, parks and films. How much do you know?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"In which country was LEGO founded?","options":[{"id":"a","text":"Sweden","is_correct":false},{"id":"b","text":"Denmark","is_correct":true},{"id":"c","text":"Germany","is_correct":false},{"id":"d","text":"The Netherlands","is_correct":false}],"explanation":"LEGO was born in Billund, Denmark, where its factory and the first Legoland park still stand."},{"id":"q2","question":"In which year was the LEGO company founded?","options":[{"id":"a","text":"1932","is_correct":true},{"id":"b","text":"1949","is_correct":false},{"id":"c","text":"1958","is_correct":false},{"id":"d","text":"1978","is_correct":false}],"explanation":"Carpenter Ole Kirk Christiansen founded it in 1932 making wooden toys; the plastic brick came decades later."},{"id":"q3","question":"The name LEGO comes from the Danish ''leg godt''. What does it mean?","options":[{"id":"a","text":"''Build together''","is_correct":false},{"id":"b","text":"''Small bricks''","is_correct":false},{"id":"c","text":"''Creative hands''","is_correct":false},{"id":"d","text":"''Play well''","is_correct":true}],"explanation":"''Leg godt'' means ''play well''; by coincidence, ''lego'' also reads as ''I put together'' in Latin."},{"id":"q4","question":"In which year was the modern LEGO brick, with its stud-and-tube system, patented?","options":[{"id":"a","text":"1949","is_correct":false},{"id":"b","text":"1958","is_correct":true},{"id":"c","text":"1963","is_correct":false},{"id":"d","text":"1972","is_correct":false}],"explanation":"The patent dates from 28 January 1958 — every brick made since still connects with that original design."},{"id":"q5","question":"What are LEGO''s little yellow figures officially called?","options":[{"id":"a","text":"Brickpeople","is_correct":false},{"id":"b","text":"Duplo figures","is_correct":false},{"id":"c","text":"Minifigures","is_correct":true},{"id":"d","text":"Blockmen","is_correct":false}],"explanation":"The minifigure, with its movable arms and legs, arrived in 1978; Duplo is the line for smaller children."},{"id":"q6","question":"What is the name of LEGO''s theme park chain?","options":[{"id":"a","text":"Legoland","is_correct":true},{"id":"b","text":"Brickland","is_correct":false},{"id":"c","text":"Legoworld","is_correct":false},{"id":"d","text":"Studland","is_correct":false}],"explanation":"The first Legoland opened next to the Billund factory in 1968 and the chain now spans several countries."},{"id":"q7","question":"In which year did The Lego Movie premiere?","options":[{"id":"a","text":"2010","is_correct":false},{"id":"b","text":"2012","is_correct":false},{"id":"c","text":"2016","is_correct":false},{"id":"d","text":"2014","is_correct":true}],"explanation":"The Lego Movie came out in February 2014 and spawned Batman and Ninjago spin-offs."},{"id":"q8","question":"What is the name of the ordinary construction worker who stars in The Lego Movie?","options":[{"id":"a","text":"Wyldstyle","is_correct":false},{"id":"b","text":"Emmet","is_correct":true},{"id":"c","text":"Benny","is_correct":false},{"id":"d","text":"Batman","is_correct":false}],"explanation":"Emmet Brickowski is ''the Special''; Wyldstyle, the spaceman Benny and Batman join his adventure."}]'::jsonb,
  null,
  array['lego', 'toys', 'pop-culture', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
