values (
  'es-trivia-lego',
  'Trivia fan de LEGO',
  'Tubos, minifiguras y una palabra danesa que significa ''juega bien'': el bloque que construyó un universo de juguetes, parques y cine. ¿Cuánto sabes?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿En qué país se fundó LEGO?","options":[{"id":"a","text":"Dinamarca","is_correct":true},{"id":"b","text":"Suecia","is_correct":false},{"id":"c","text":"Alemania","is_correct":false},{"id":"d","text":"Países Bajos","is_correct":false}],"explanation":"LEGO nació en Billund, Dinamarca, donde siguen su fábrica y el primer parque Legoland."},{"id":"q2","question":"¿En qué año se fundó la empresa LEGO?","options":[{"id":"a","text":"1949","is_correct":false},{"id":"b","text":"1958","is_correct":false},{"id":"c","text":"1932","is_correct":true},{"id":"d","text":"1978","is_correct":false}],"explanation":"El carpintero Ole Kirk Christiansen la fundó en 1932 haciendo juguetes de madera; el bloque de plástico llegó décadas después."},{"id":"q3","question":"El nombre LEGO viene del danés ''leg godt''. ¿Qué significa?","options":[{"id":"a","text":"''Juega bien''","is_correct":true},{"id":"b","text":"''Construye junto''","is_correct":false},{"id":"c","text":"''Ladrillos pequeños''","is_correct":false},{"id":"d","text":"''Manos creativas''","is_correct":false}],"explanation":"''Leg godt'' significa ''juega bien''; por coincidencia, ''lego'' también se lee como ''yo ensamblo'' en latín."},{"id":"q4","question":"¿En qué año se patentó el bloque moderno de LEGO, con su sistema de tubos?","options":[{"id":"a","text":"1958","is_correct":true},{"id":"b","text":"1949","is_correct":false},{"id":"c","text":"1965","is_correct":false},{"id":"d","text":"1972","is_correct":false}],"explanation":"La patente es del 28 de enero de 1958: todos los bloques fabricados desde entonces siguen encajando con ese diseño."},{"id":"q5","question":"¿Cómo se llaman oficialmente las pequeñas figuras amarillas de LEGO?","options":[{"id":"a","text":"Figuras Duplo","is_correct":false},{"id":"b","text":"Minifiguras","is_correct":true},{"id":"c","text":"Hombrecillos de bloques","is_correct":false},{"id":"d","text":"Personajes LEGO","is_correct":false}],"explanation":"La minifigura, con brazos y piernas móviles, llegó en 1978; Duplo es la línea para los más pequeños."},{"id":"q6","question":"¿Cómo se llama la cadena de parques temáticos de LEGO?","options":[{"id":"a","text":"Brickland","is_correct":false},{"id":"b","text":"Mundo LEGO","is_correct":false},{"id":"c","text":"Legoland","is_correct":true},{"id":"d","text":"Ciudad LEGO","is_correct":false}],"explanation":"El primer Legoland abrió junto a la fábrica de Billund en 1968 y la cadena hoy abarca varios países."},{"id":"q7","question":"¿En qué año se estrenó La gran aventura LEGO (The Lego Movie)?","options":[{"id":"a","text":"2014","is_correct":true},{"id":"b","text":"2010","is_correct":false},{"id":"c","text":"2012","is_correct":false},{"id":"d","text":"2017","is_correct":false}],"explanation":"La película se estrenó en febrero de 2014 y generó las derivaciones de Batman y Ninjago."},{"id":"q8","question":"¿Cómo se llama el trabajador de la construcción que protagoniza la película?","options":[{"id":"a","text":"Estilo-Libre","is_correct":false},{"id":"b","text":"Benny","is_correct":false},{"id":"c","text":"Batman","is_correct":false},{"id":"d","text":"Emmet","is_correct":true}],"explanation":"Emmet Brickowski es ''el Especial''; Estilo-Libre, el astronauta Benny y Batman lo acompañan."}]'::jsonb,
  null,
  array['lego', 'juguetes', 'cultura pop', 'trivia']::text[],
  3,
  'published',
